text:
{
  "tasks": [
    {
      "task_id": "T1",
      "title": "已完成任务按项目统计数量并升序排列",
      "business_question": "仅分析状态为“已完成”的任务，按项目分组统计任务数量，并按数量升序排列。不要推断差异原因。",
      "priority": "P0",
      "priority_reason": "删除后无法回答核心问题：用户明确要求针对已完成任务的项目分布及排序，这是决策的唯一依据。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "sort",
          "params": {
            "field": "task_count",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
